// Merges UG_MOVES over a generation's move table (used from moves.ts).
export function applyUGMoves(table: {[name: string]: any}) {
  for (const name of Object.keys(UG_MOVES)) {
    const {extra, ...core} = UG_MOVES[name];
    table[name] = table[name] ? Object.assign({}, table[name], core) : Object.assign({}, core, extra);
  }
}
